const $=id=>document.getElementById(id);
let recordings=[],selected=0,total=0,wantsPlay=false,started=false,video=$('broadcast'),standby=$('standby');
const slots=[video,standby];
function hour(start,seconds=0){const d=new Date(start.replace(' ','T')+'-04:00');return new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit',second:seconds?'2-digit':undefined}).format(new Date(d.getTime()+seconds*1000))}
function duration(seconds){seconds=Math.max(0,Math.floor(seconds));return `${Math.floor(seconds/3600)}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function position(){const r=recordings[selected];return r?Math.min(total,r.elapsed+Math.max(0,video.currentTime-r.offset)):0}
function updateClock(){const r=recordings[selected];if(!r)return;$('clock').textContent='≈ '+hour(r.start,Math.max(r.offset,video.currentTime))+' EDT';$('progress').value=position();$('elapsed').textContent=duration(position())+' / '+duration(total);$('progress').setAttribute('aria-valuetext',$('clock').textContent)}
function setState(s){$('state').textContent=s}
function buttons(){$('playPause').textContent=wantsPlay?'Ⅱ Pause':'▶ Play';$('playPause').setAttribute('aria-label',wantsPlay?'Pause broadcast':'Play broadcast')}
function showError(message){$('loading').hidden=true;$('error').hidden=false;$('errorText').textContent=message;wantsPlay=false;buttons();setState('PLAYBACK UNAVAILABLE')}
function prepare(el,index,time){el.dataset.index=String(index);el.dataset.target=String(time);el.preload=el===video?'auto':'metadata';el.src=recordings[index].url;el.load()}
function prefetch(){if(selected+1>=recordings.length)return;if(Number(standby.dataset.index)!==selected+1)prepare(standby,selected+1,recordings[selected+1].offset);if(video.duration-video.currentTime<60&&standby.preload!=='auto')standby.preload='auto'}
function play(){if(!recordings.length)return;started=true;wantsPlay=true;buttons();$('startScreen').hidden=true;if(Number(video.dataset.index)!==selected||video.readyState<1){$('loading').hidden=false;return}const active=video;active.play().catch(()=>{if(active!==video)return;wantsPlay=false;buttons();setState('PRESS PLAY TO CONTINUE');$('loading').hidden=true})}
function activate(index,time,autoplay){const incoming=standby;video.pause();video.hidden=true;standby=video;video=incoming;video.hidden=false;video.muted=standby.muted;selected=index;wantsPlay=autoplay;buttons();$('error').hidden=true;$('loading').hidden=!autoplay;const r=recordings[index];$('source').href=r.source;$('errorSource').href=r.source;setState(autoplay?'CONTINUING BROADCAST':'PAUSED');
 if(Number(video.dataset.index)===index&&video.readyState>=1){video.currentTime=time;updateClock();if(autoplay)play();prefetch()}else prepare(video,index,time);
}
function seek(seconds){if(!recordings.length)return;seconds=Math.max(0,Math.min(total-.1,seconds));const index=recordings.findIndex(r=>seconds<r.elapsed+r.duration-r.offset);const r=recordings[index],target=r.offset+seconds-r.elapsed;if(index===selected){video.currentTime=target;updateClock()}else activate(index,target,wantsPlay)}
for(const el of slots){el.addEventListener('loadedmetadata',()=>{el.currentTime=Number(el.dataset.target)||0;if(el===video){updateClock();if(wantsPlay)play();prefetch()}});el.addEventListener('playing',()=>{if(el!==video)return;wantsPlay=true;buttons();$('loading').hidden=true;$('error').hidden=true;$('startScreen').hidden=true;setState('ORIGINAL BROADCAST')});el.addEventListener('waiting',()=>{if(el===video&&wantsPlay){$('loading').hidden=false;setState('BUFFERING')}});el.addEventListener('timeupdate',()=>{if(el===video){updateClock();prefetch()}});el.addEventListener('error',()=>{if(el===video)showError('The broadcast could not load. Try again to resume, or open the original source.');else el.dataset.index='-1'});el.addEventListener('ended',()=>{if(el!==video)return;if(selected+1<recordings.length)activate(selected+1,recordings[selected+1].offset,true);else{wantsPlay=false;buttons();updateClock();setState('END OF SEPTEMBER 11 COVERAGE')}})}
$('begin').onclick=play;$('playPause').onclick=()=>{if(!recordings.length)return;if(wantsPlay){wantsPlay=false;video.pause();buttons();$('loading').hidden=true;setState('PAUSED')}else{if(video.ended&&selected===recordings.length-1)seek(0);play()}};$('rewind').onclick=()=>seek(position()-30);$('forward').onclick=()=>seek(position()+30);$('progress').onchange=()=>seek(Number($('progress').value));$('mute').onclick=()=>{video.muted=!video.muted;standby.muted=video.muted;$('mute').textContent=video.muted?'Unmute':'Mute';$('mute').setAttribute('aria-pressed',String(video.muted))};$('retry').onclick=()=>{wantsPlay=true;buttons();prepare(video,selected,Math.max(recordings[selected].offset,video.currentTime||0))};$('theater').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.television').requestFullscreen()}catch{document.body.classList.toggle('theater')}};$('about').onclick=()=>$('details').showModal();$('close').onclick=()=>$('details').close();
fetch('archive.json').then(r=>{if(!r.ok)throw new Error('Archive index unavailable');return r.json()}).then(data=>{if(!Array.isArray(data)||!data.length)throw new Error('No recordings indexed');recordings=data.map(r=>{const copy={...r,elapsed:total};total+=r.duration-r.offset;return copy});$('progress').max=total;$('coverage').textContent=(total/3600).toFixed(1)+' hours · one continuous broadcast';$('begin').disabled=false;$('begin').textContent='▶  Watch original coverage';document.querySelectorAll('.playback button, .playback input').forEach(el=>el.disabled=false);video.dataset.index='-1';standby.dataset.index='-1';$('source').href=recordings[0].source;$('errorSource').href=recordings[0].source;prepare(video,0,recordings[0].offset);updateClock()}).catch(()=>{$('begin').textContent='Archive unavailable';showError('The archive could not load. Please refresh or visit the Internet Archive.');$('errorSource').href='https://archive.org/details/911'});
